 return <section><h1>Tickety</h1><SearchDraft key={filters.q} value={filters.q} onCommit={q=>filters.update({q})}/><label>Status<select value={filters.status??""} onChange={e=>{const value=e.currentTarget.value;if(value===""||isStatus(value))filters.update({status:value||null});}}><option value="">Wszystkie</option><option value="OPEN">Otwarte</option><option value="IN_PROGRESS">W toku</option><option value="CLOSED">Zamknięte</option></select></label><label>Sortowanie<select value={filters.sort} onChange={e=>{const value=e.currentTarget.value;if(isSort(value))filters.update({sort:value});}}>{sorts.map(sort=><option key={sort}>{sort}</option>)}</select></label><button type="button" onClick={filters.clear}>Wyczyść filtry</button><p role="status">Wyników: {page.total}. Strona {filters.page}.</p>{page.items.length?<ul>{page.items.map(row=><li key={row.id}><Link to={ticketPath(row.id)} state={{fromList:listUrl}}>{row.title}</Link></li>)}</ul>:<p>Brak wyników na tej stronie. <button type="button" onClick={()=>filters.update({page:1},{replace:true,resetPage:false})}>Pierwsza strona</button></p>}<nav aria-label="Strony listy"><button type="button" disabled={filters.page<=1} onClick={()=>filters.update({page:filters.page-1},{replace:false,resetPage:false})}>Poprzednia</button><button type="button" disabled={filters.page>=page.pageCount} onClick={()=>filters.update({page:filters.page+1},{replace:false,resetPage:false})}>Następna</button></nav></section>;
}

