import type {Filters,Status} from "./filters";export type Row={id:number;title:string;status:Status;priority:number;createdAt:number};
export const rows:Row[]=[{id:7,title:"API wyszukiwania",status:"OPEN",priority:2,createdAt:1},{id:42,title:"API logowania",status:"CLOSED",priority:3,createdAt:2},{id:481,title:"API eksportu",status:"IN_PROGRESS",priority:1,createdAt:3},{id:482,title:"Nowe kolory",status:"OPEN",priority:1,createdAt:4},{id:483,title:"Nowa nawigacja",status:"OPEN",priority:3,createdAt:5},{id:484,title:"API statystyk",status:"CLOSED",priority:2,createdAt:6}];
export function selectPage(source:readonly Row[],filters:Filters,pageSize=2){const selected=source.filter(row=>(!filters.status||row.status===filters.status)&&row.title.toLocaleLowerCase("pl").includes(filters.q.toLocaleLowerCase("pl"))).sort((a,b)=>{let value=filters.sort==="title:asc"?a.title.localeCompare(b.title,"pl"):filters.sort==="priority:desc"?b.priority-a.priority:filters.sort==="createdAt:asc"?a.createdAt-b.createdAt:b.createdAt-a.createdAt;return value||a.id-b.id;});const start=(filters.page-1)*pageSize;return {items:selected.slice(start,start+pageSize),total:selected.length,pageCount:Math.ceil(selected.length/pageSize)};}

import {useEffect,useRef,useState} from "react";export function DebouncedDraft({value,onCommit}:{value:string;onCommit:(q:string)=>void}){const [draft,setDraft]=useState(value);const commit=useRef(onCommit);useEffect(()=>{commit.current=onCommit;},[onCommit]);useEffect(()=>{if(draft===value)return;const timer=setTimeout(()=>commit.current(draft),300);return ()=>clearTimeout(timer);},[draft,value]);return <input type="search" aria-label="Szukaj ticketów" value={draft} onChange={event=>setDraft(event.currentTarget.value)}/>;}
