export const statuses=["OPEN","IN_PROGRESS","CLOSED"] as const;
export const sorts=["createdAt:desc","createdAt:asc","priority:desc","title:asc"] as const;
export type Status=typeof statuses[number];export type Sort=typeof sorts[number];
export type Filters={status:Status|null;q:string;sort:Sort;page:number};
export type Changes=Partial<Filters>;
export const isStatus=(value:string|null):value is Status=>statuses.some(item=>item===value);
export const isSort=(value:string|null):value is Sort=>sorts.some(item=>item===value);
export function readFilters(params:URLSearchParams):Filters{const status=params.get("status"),sort=params.get("sort"),raw=params.get("page");const n=raw!==null&&/^[1-9]\d*$/.test(raw)?Number(raw):NaN;return {status:isStatus(status)?status:null,q:params.get("q")??"",sort:isSort(sort)?sort:"createdAt:desc",page:Number.isSafeInteger(n)?n:1};}
export function patchFilters(previous:URLSearchParams,changes:Changes,resetPage=true){if(changes.page!==undefined&&(!Number.isSafeInteger(changes.page)||changes.page<1))throw new RangeError("Niepoprawna strona");const next=new URLSearchParams(previous);for(const [key,value]of Object.entries(changes)){if(value===undefined)continue;if(value===null||value===""||(key==="page"&&value===1)||(key==="sort"&&value==="createdAt:desc"))next.delete(key);else next.set(key,String(value));}if(resetPage&&changes.page===undefined)next.delete("page");return next;}
export function clearFilters(previous:URLSearchParams){const next=new URLSearchParams(previous);for(const key of ["status","q","sort","page"])next.delete(key);return next;}
export function listKey(filters:Filters){return ["tickets","list",filters.status,filters.q,filters.sort,filters.page] as const;}
export function apiParams(filters:Filters){const params=new URLSearchParams({sort:filters.sort,page:String(filters.page)});if(filters.status)params.set("status",filters.status);if(filters.q)params.set("q",filters.q);return params;}

